// Hot-topic aggregation composes the site's existing cards and advertisement carousel.
export function renderAggregation({catalog, movies, card, esc, homeAdRow, startHomeAds, centerApps=[], appIcon}) {
  const root = document.querySelector('#app');
  const params = new URLSearchParams(location.search);
  // Demo archive: two releases per month, newest first.
  const periods = Array.from({length:20},(_,i)=>`2026-${String(10-Math.floor(i/2)).padStart(2,'0')}-${i%2===0?'2':'1'}`);
  const period = periods.includes(params.get('period')) ? params.get('period') : periods[0];
  const periodIndex = periods.indexOf(period);
  // Preview playback figures are independent of the catalog's heat score.
  const previewPlays = Math.max(3900000,28600000-periodIndex*1250000);
  const updatedDate = `${period.split('-')[1]}.${period.endsWith('-1')?'01':'16'}`;
  const nextRelease = new Date(Date.UTC(Number(period.slice(0,4)),Number(period.slice(5,7))-(period.endsWith('-1')?1:0),period.endsWith('-1')?16:1));
  const nextReleaseLabel = `${String(nextRelease.getUTCMonth()+1).padStart(2,'0')}/${String(nextRelease.getUTCDate()).padStart(2,'0')}`;
  const label = value => {const [year,month,half]=value.split('-');return `${year} · ${month}月${half==='1'?'上':'下'}半月`};
  const unique = items => [...new Map(items.map(m=>[m.id,m])).values()];
  const themes = (catalog.themeDetails || []).map(t=>({...t,items:unique(t.blocks.flatMap(b=>b.items))})).filter(t=>t.items.length);
  const topics = themes.map((t,i)=>({...t,items:t.items.map(m=>movies.find(x=>x.id===m.id)||m),key:String(i)}));
  const rotated = topics.slice(periodIndex).concat(topics.slice(0,periodIndex));
  const selected = rotated.find(t=>t.key===params.get('topic'));
  let visibleCount=4, allWords=false, rankingCategory='视频';

  const allItems=unique(rotated.flatMap(t=>t.items));
  const heat = m => {const raw=String(m.heat||'0');return parseFloat(raw.replace(/[^0-9.]/g,''))*(/[w万]/i.test(raw)?10000:1)||0};
  const number = n => n>=100000000?`${(n/100000000).toFixed(1)}亿`:n>=10000?`${(n/10000).toFixed(1)}万`:n.toLocaleString('zh-CN');
  const url = (p=period,key='') => `/hot-topics?${new URLSearchParams({period:p,...(key!==''?{topic:key}:{})})}`;
  const heading = text=>`<h2><img src="/assets/theme-flame.png" width="24" height="24" alt="">${text}</h2>`;
  const topicHeat=t=>t.items.reduce((sum,m)=>sum+heat(m),0);
  function rankList(){
    const ranked=allItems.filter(m=>(m.contentType||'视频')===rankingCategory).sort((a,b)=>heat(b)-heat(a)).slice(0,10);
    return ranked.map((m,i)=>`<li><a href="/movie/detail/${esc(m.slug||m.id)}-${esc(m.id)}"><b class="ag-rank ag-rank-${i+1}">${i+1}</b><span>${esc(m.name)}</span><small>${number(heat(m))}</small></a></li>`).join('') || '<li class="ag-no-results">本期暂无该分类内容</li>';
  }
  const allUrl = (key,page=1) => `/hot-topics?${new URLSearchParams({period,topic:key,view:'all',page:String(page)})}`;
  const contentIcon = '<span class="ag-content-icon" aria-hidden="true"><img src="/assets/aggregation-all-content.png" alt=""></span>';
  function group(t){return `<article class="ag-topic" id="topic-${t.key}"><div class="ag-topic-heading"><div><span class="ag-eyebrow">TOP ${rotated.indexOf(t)+1} <span>· ${t.items.length} 部相关影片</span></span><h3>${esc(t.name)}</h3></div><div class="ag-heat"><strong>${number(topicHeat(t))}</strong><small>内容累计热度</small></div></div><p class="ag-description">${esc(t.description||`围绕${t.name}，发现更多值得观看的作品。`)}</p><div class="ag-film-grid">${t.items.slice(0,4).map((m,n)=>card(m,n)).join('')}</div><a class="ag-more" href="${allUrl(t.key)}">查看全部 ${t.items.length} 部相关影片 <span aria-hidden="true">›</span></a></article>`}
  function drawAll(t){
    const pageSize=24,total=t.items.length,pages=Math.max(1,Math.ceil(total/pageSize));
    const requested=Number(params.get('page')),page=Number.isSafeInteger(requested)?Math.max(1,Math.min(pages,requested)):1;
    const pageLink=(value,text,disabled=false)=>disabled?`<span class="ag-page-disabled" aria-disabled="true">${text}</span>`:`<a href="${allUrl(t.key,value)}" ${value===page?'class="selected" aria-current="page"':''}>${text}</a>`;
    document.title=`${t.name} - 全部相关影片 - 万象影视`;
    root.innerHTML=`<div class="aggregation ag-all-page">${homeAdRow(0)}<a class="ag-back" href="${url()}"><img src="/assets/player-back.svg" width="18" height="18" alt="">返回热搜聚合页</a><section class="ag-hero ag-all-hero" aria-labelledby="ag-all-title"><img class="ag-hero-background" src="/assets/aggregation-all-banner.png" alt=""><div class="ag-hero-copy"><span class="ag-live-badge ag-all-badge">${contentIcon}<span>全部内容</span></span><h1 id="ag-all-title">${esc(t.name)}</h1><p>${esc(t.description||`围绕${t.name}，发现更多值得观看的作品。`)}</p><dl class="ag-hero-metrics"><div><dd>${total}</dd><dt>相关内容</dt></div><div><dd>${number(topicHeat(t))}</dd><dt>热度</dt></div></dl></div></section><section class="ag-all-results" aria-labelledby="ag-all-heading"><div class="ag-section-heading"><h2 id="ag-all-heading">${contentIcon}全部内容列表</h2><span>共 ${total} 部相关影片</span></div><div class="ag-film-grid ag-all-grid">${t.items.slice((page-1)*pageSize,page*pageSize).map((m,n)=>card(m,n)).join('')||'<div class="rank-empty"><img src="/assets/category-empty.png" alt=""><p>暂无相关影片</p></div>'}</div><nav class="pagination ag-all-pagination" aria-label="相关影片分页">${pageLink(page-1,'上一页',page===1)}${Array.from({length:pages},(_,i)=>pageLink(i+1,String(i+1))).join('')}${pageLink(page+1,'下一页',page===pages)}<span>共 ${total} 条</span></nav></section><section class="ag-related-apps" aria-label="推荐应用"><div class="ag-app-track">${centerApps.slice(0,16).map(a=>`<button class="app-tile" type="button" data-center-app="${a.id}" aria-label="查看${esc(a.name)}">${appIcon(a)}<span class="app-tile-name">${esc(a.name)}</span></button>`).join('')}</div></section>${homeAdRow(2)}</div>`;
    startHomeAds();
  }
  const archiveUrl = `/hot-topics?${new URLSearchParams({period,view:'archive'})}`;
  function drawArchive(){
    document.title='全部周期历史 - 万象影视';
    root.innerHTML=`<div class="aggregation ag-all-page ag-archive-page">${homeAdRow(0)}<a class="ag-back" href="${url()}"><img src="/assets/player-back.svg" width="18" height="18" alt="">返回热搜聚合页</a><section class="ag-hero ag-archive-hero" aria-labelledby="ag-archive-title"><img class="ag-hero-background" src="/assets/aggregation-archive-banner.png" alt=""><div class="ag-hero-copy"><span class="ag-live-badge"><img src="/assets/aggregation-archive.png" width="36" height="36" alt=""><span>历史归档</span></span><h1 id="ag-archive-title">全部周期历史</h1><p>选择任一周期可查看该期热词、内容专题和榜单。</p><dl class="ag-hero-metrics"><div><dd>${periods.length}<small> 个</small></dd><dt>已发布周期</dt></div></dl><span class="ag-archive-order">按时间倒序</span></div></section><section class="ag-archive-results" aria-labelledby="ag-archive-heading"><div class="ag-section-heading"><h2 id="ag-archive-heading"><img src="/assets/aggregation-archive.png" width="24" height="24" alt="">周期归档</h2><span>最近更新：<time datetime="2026-10-16">2026-10-16</time></span></div><div class="ag-period-grid">${periods.map((p,i)=>{const t=topics[i%topics.length];return `<article class="ag-period-card"><time datetime="${p.slice(0,7)}-${p.endsWith('-1')?'01':'16'}">${label(p)}</time><h3>${esc(t?.name||'热门影视专题')}</h3><p><strong>${topics.length}</strong> 个热词</p><a class="ag-period-open" href="${url(p)}" aria-label="查看${label(p)}内容">查看该期内容 <span aria-hidden="true">→</span></a></article>`}).join('')}</div></section><section class="ag-related-apps" aria-label="推荐应用"><div class="ag-app-track">${centerApps.slice(0,16).map(a=>`<button class="app-tile" type="button" data-center-app="${a.id}" aria-label="查看${esc(a.name)}">${appIcon(a)}<span class="app-tile-name">${esc(a.name)}</span></button>`).join('')}</div></section>${homeAdRow(2)}</div>`;
    startHomeAds();
  }
  const faqs=[['本期专题覆盖哪些时间？',`当前为${label(period)}专题。上半月范围为每月 1—15 日，下半月为 16 日至月末；可以通过上方期数或历史归档切换。`],['热词与相关影片如何关联？','热词按站内已有推荐主题整理，每个主题下展示对应的影片。点击影片封面可进入详情，点击“查看全部”可进入该主题的完整列表，并翻页浏览。'],['榜单和统计数据来自哪里？','当前为功能预览，影片与热度来自站内展示资料，期数、累计播放、更新日期及榜单为示例数据。尚未接入实时热搜、外部指数或真实播放统计；接入接口后可替换为真实数据。'],['如何快速找到想看的内容？','选择热词可聚焦一个主题；播放榜可按视频、短视频、漫画、小说筛选。也可以使用网站顶部搜索框查找片名。'],['如何返回本期全部热词？','再次点击已选中的热词，或点击内容区的“查看全部热词”，即可恢复本期所有主题。浏览器前进、后退也会保留所选择的期数和热词。']];
  function draw(){
    const shown=selected?[selected]:rotated.slice(0,visibleCount);
    document.title='热搜专题 - 万象影视';
    root.innerHTML=`<div class="aggregation"><nav class="ag-breadcrumb" aria-label="面包屑"><a href="/">首页</a><span aria-hidden="true">/</span><span>热搜专题</span></nav><section class="ag-hero" aria-labelledby="ag-hero-title"><img class="ag-hero-background" src="/assets/aggregation-banner.png" alt="" aria-hidden="true" fetchpriority="high"><div class="ag-hero-copy"><span class="ag-live-badge" title="专题预览状态"><img src="/assets/aggregation-hot.png" width="36" height="36" alt="" aria-hidden="true"><span>实时更新</span></span><h1 id="ag-hero-title">${esc(rotated[0]?.name||'发现万象好故事')}</h1><p>${esc(rotated[0]?.description||'汇聚热门话题与精彩片单。')} 本期聚合热门影视话题与相关作品，围绕剧情、人物和精彩故事整理专题内容。从热词出发，发现值得关注的影片，一站查看相关片单与热门内容。</p><dl class="ag-hero-metrics"><div><dd>${topics.length}</dd><dt>热词</dt></div><div><dd>${allItems.length}</dd><dt>相关内容</dt></div><div><dd><time>${updatedDate.replace('.','/')} 12:20</time></dd><dt>最近更新</dt></div><div><dd><time datetime="${nextRelease.toISOString().slice(0,10)}">${nextReleaseLabel}</time></dd><dt>下期发布</dt></div></dl></div></section><nav class="ag-periods" aria-label="专题期数">${(periodIndex<6?periods.slice(0,6):[...periods.slice(0,5),period]).map(p=>`<a href="${url(p)}" ${p===period?'aria-current="page"':''}>${label(p)}</a>`).join('')}<a href="${archiveUrl}" class="ag-archive-link">全部期数 <span aria-hidden="true">+</span></a></nav><dl class="ag-statistics" aria-label="专题统计"><div class="ag-stat-item"><dt><span class="ag-stat-icon" aria-hidden="true"><img src="/assets/aggregation-stat-words.png" width="54" height="54" alt=""></span>热词数</dt><dd>${topics.length}<small>个</small></dd></div><div class="ag-stat-item"><dt><span class="ag-stat-icon" aria-hidden="true"><img src="/assets/aggregation-stat-content.png" width="54" height="54" alt=""></span>相关内容</dt><dd>${allItems.length}<small>部</small></dd></div><div class="ag-stat-item"><dt><span class="ag-stat-icon" aria-hidden="true"><img src="/assets/aggregation-stat-plays.png" width="54" height="54" alt=""></span>累计播放</dt><dd>${(previewPlays/1000000).toFixed(1)}M</dd></div><div class="ag-stat-item"><dt><span class="ag-stat-icon" aria-hidden="true"><img src="/assets/aggregation-stat-date.png" width="54" height="54" alt=""></span>更新日期</dt><dd><time datetime="${period.slice(0,7)}-${period.endsWith('-1')?'01':'16'}">${updatedDate}</time></dd></div><div class="ag-stat-item"><dt><span class="ag-stat-icon" aria-hidden="true"><img src="/assets/aggregation-stat-top.png" width="54" height="54" alt=""></span>本站热度榜</dt><dd>TOP.1</dd></div></dl><div class="ag-layout"><div class="ag-main"><section class="ag-panel ag-words" aria-labelledby="ag-words-title"><div class="ag-section-heading"><h2 id="ag-words-title"><img class="ag-hot-icon" src="/assets/aggregation-hot.png" width="24" height="24" alt="" aria-hidden="true">本期全部热词</h2><span>${topics.length} 个热词</span></div><div class="ag-word-list">${rotated.slice(0,allWords?rotated.length:12).map((t,i)=>`<a href="${url(period,selected?.key===t.key?'':t.key)}" ${selected?.key===t.key?'aria-current="true"':''}>${esc(t.name)}<small>${t.items.length}</small>${i===0?'<em class="ag-badge ag-badge-top">TOP</em>':i===1?'<em class="ag-badge ag-badge-new">NEW</em>':''}</a>`).join('')}</div>${topics.length>12?`<button type="button" class="ag-more" data-ag-words aria-expanded="${allWords}">${allWords?'收起热词':`展开其余 ${topics.length-12} 个热词`} <span aria-hidden="true">${allWords?'↑':'↓'}</span></button>`:''}</section><section aria-label="热词内容聚合"><div class="ag-section-heading ag-results-heading">${heading(selected?'当前热词内容':'本期 TOP 热词内容聚合')}${selected?`<a href="${url()}">查看全部热词 ›</a>`:'<span>精选主题片单</span>'}</div><div class="ag-groups">${shown.map(group).join('')}</div>${!selected&&visibleCount<rotated.length?`<button class="ag-load" data-ag-load type="button">继续加载 · 剩余 ${rotated.length-visibleCount} 个热词 <span aria-hidden="true">↓</span></button>`:''}</section>${homeAdRow(2)}<section class="ag-panel ag-faq">${heading('关于热搜专题')}${faqs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}<span aria-hidden="true"></span></summary><p>${a}</p></details>`).join('')}</section></div><aside class="ag-sidebar" aria-label="热搜榜单和归档"><section class="ag-panel"><div class="ag-section-heading"><h2><span class="ag-sidebar-icon ag-sidebar-icon-rank" aria-hidden="true"><img src="/assets/aggregation-rank.png" width="24" height="24" alt=""></span>本站内容热度榜</h2><span>TOP 10</span></div><div class="ag-rank-tabs" role="group" aria-label="热度榜分类">${['视频','短视频','漫画','小说'].map(c=>`<button type="button" data-ag-rank="${c}" aria-pressed="${rankingCategory===c}">${c}</button>`).join('')}</div><ol class="ag-rank-list" id="ag-ranking">${rankList()}</ol></section><section class="ag-panel"><div class="ag-section-heading"><h2><span class="ag-sidebar-icon ag-sidebar-icon-trend" aria-hidden="true"><img src="/assets/aggregation-trend.png" width="24" height="24" alt=""></span>近14天飙升榜</h2><span>示例趋势</span></div><ol class="ag-rank-list">${[...rotated].map((t,i)=>({...t,growth:Math.max(12,234-i*17-periodIndex*3)})).sort((a,b)=>b.growth-a.growth).slice(0,10).map((t,i)=>`<li><a href="${url(period,t.key)}"><b class="ag-rank ag-rank-${i+1}">${i+1}</b><span>${esc(t.name)}</span><small class="ag-growth">↑ ${t.growth}%</small></a></li>`).join('')}</ol></section><section class="ag-panel"><div class="ag-section-heading"><h2><span class="ag-sidebar-icon ag-sidebar-icon-archive" aria-hidden="true"><img src="/assets/aggregation-archive.png" width="24" height="24" alt=""></span>热搜归档</h2><a href="${archiveUrl}">全部期数 ›</a></div><div class="ag-archives">${periods.slice(1,6).map((p,i)=>`<a href="${url(p)}"><time>${label(p)}</time><strong>${esc(topics[(i+1)%topics.length]?.name||'热门影视专题')}</strong></a>`).join('')}</div></section><section class="ag-panel ag-note"><h2><span class="ag-sidebar-icon ag-sidebar-icon-notice" aria-hidden="true"><img src="/assets/aggregation-notice.png" width="24" height="24" alt=""></span>专题说明</h2><p>当前专题使用站内影片资料展示，期数、累计播放、更新日期和榜单为示例数据，用于功能预览，不代表实时热搜排行。</p></section></aside></div></div>`;
    startHomeAds();
  }
  if(params.get('view')==='archive'){drawArchive();return;}
  if(params.get('view')==='all'){
    if(selected)drawAll(selected);
    else{document.title='专题未找到 - 万象影视';root.innerHTML=`<div class="aggregation"><div class="rank-empty"><img src="/assets/category-empty.png" alt=""><p>未找到这个热搜专题</p><a class="ag-more" href="${url()}">返回热搜聚合页</a></div></div>`;}
    return;
  }
  draw();
  // One root handler is replaced on route entry, so rerenders never accumulate listeners.
  root.onclick=e=>{
    const b=e.target.closest('button');if(!b||!b.matches('[data-ag-load],[data-ag-words],[data-ag-rank]'))return;
    if(b.hasAttribute('data-ag-rank')){rankingCategory=b.dataset.agRank;root.querySelectorAll('[data-ag-rank]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));root.querySelector('#ag-ranking').innerHTML=rankList();return}
    const focusSelector=b.hasAttribute('data-ag-load')?'[data-ag-load]':'[data-ag-words]';
    const oldY=window.scrollY;
    if(b.hasAttribute('data-ag-load'))visibleCount+=4;
    if(b.hasAttribute('data-ag-words'))allWords=!allWords;
    draw();
    const target=root.querySelector(focusSelector);target?.focus({preventScroll:true});
    window.scrollTo({top:oldY,behavior:'instant'});
  };
}
